import { CommonModule } from '@angular/common';
import { Component, OnInit,ChangeDetectorRef } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { KanbanModule } from '@syncfusion/ej2-angular-kanban';
import { CreateTaskRequest, TaskDto, TaskService, TaskState, UpdateTaskRequest } from '../Service/TaskService';

@Component({
  selector: 'app-task-manager',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule, KanbanModule],
  templateUrl: './task-manager.html',
  styleUrl: './task-manager.css',
})
export class TaskManager implements OnInit {
  tasks: TaskDto[] = [];
  loading = false;
  saving = false;
  error = '';
  showForm = false;
  editMode = false;
  editingTaskId: number | null = null;
  selectedUserStoryId: number | null = null;
  readonly kanbanColumns: { headerText: string; keyField: string }[] = [
    { headerText: 'À faire', keyField: 'pending,todo' },
    { headerText: 'En cours', keyField: 'inProgress' },
    { headerText: 'En révision', keyField: 'validated' },
    { headerText: 'Terminé', keyField: 'done' }
  ];
  readonly kanbanOrder: TaskState[] = ['pending', 'todo', 'inProgress', 'done', 'validated'];
  readonly boardColumns: { id: string; title: string; dotClass: string; statuses: TaskState[]; createStatus: TaskState }[] = [
    { id: 'todo', title: 'À faire', dotClass: 'dot-gray', statuses: ['pending', 'todo'], createStatus: 'todo' },
    { id: 'inProgress', title: 'En cours', dotClass: 'dot-blue', statuses: ['inProgress'], createStatus: 'inProgress' },
    { id: 'validated', title: 'En révision', dotClass: 'dot-orange', statuses: ['validated'], createStatus: 'validated' },
    { id: 'done', title: 'Terminé', dotClass: 'dot-green', statuses: ['done'], createStatus: 'done' }
  ];

  statusOptions: { value: TaskState; label: string }[] = [
    { value: 'pending', label: 'Pending' },
    { value: 'todo', label: 'To Do' },
    { value: 'inProgress', label: 'In Progress' },
    { value: 'done', label: 'Done' },
    { value: 'validated', label: 'Validated' }
  ];

  formModel: CreateTaskRequest = this.getEmptyForm();

  constructor(
    private taskService: TaskService,
    private route: ActivatedRoute,
    private router: Router,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.route.params.subscribe((params) => {
      const userStoryIdParam = params['userStoryId'];
      const taskIdParam = params['id'];
      this.selectedUserStoryId = userStoryIdParam ? Number(userStoryIdParam) : null;

      if (this.selectedUserStoryId) {
        this.formModel.userStoryId = this.selectedUserStoryId;
      }

      this.loadTasks();

      if (taskIdParam) {
        this.loadTaskForEdit(Number(taskIdParam));
      }
    });
  }

  loadTasks(): void {
    this.loading = true;
    this.error = '';

    this.taskService.getAll().subscribe({
      next: (data) => {
        const safeData = Array.isArray(data) ? data : [];
        this.tasks = this.selectedUserStoryId
          ? safeData.filter(task => task.userStoryId === this.selectedUserStoryId)
          : safeData;
        this.loading = false;
        this.cdr.detectChanges();
      },
      error: () => {
        this.error = 'Erreur lors du chargement des tâches';
        this.loading = false;
      }
    });
  }

  startCreate(): void {
    this.showForm = true;
    this.editMode = false;
    this.editingTaskId = null;
    this.formModel = this.getEmptyForm();
    if (this.selectedUserStoryId) {
      this.formModel.userStoryId = this.selectedUserStoryId;
    }
  }

  startEdit(task: TaskDto, event: Event): void {
    event.stopPropagation();
    this.showForm = true;
    this.editMode = true;
    this.editingTaskId = task.id;
    this.formModel = {
      title: task.title,
      description: task.description,
      estimatedHours: task.estimatedHours,
      status: this.normalizeStatus(task.status),
      complexity: task.complexity ?? 1,
      startDate: this.toDateInput(task.startDate),
      endDate: this.toDateInput(task.endDate),
      userStoryId: task.userStoryId,
      assignedToId: task.assignedToId ?? null,
      sprintId: task.sprintId ?? null
    };
  }

  saveTask(): void {
    if (!this.formModel.title.trim() || !this.formModel.userStoryId) {
      this.error = 'Titre et User Story sont obligatoires';
      return;
    }

    this.saving = true;
    this.error = '';

    if (this.editMode && this.editingTaskId) {
      const request: UpdateTaskRequest = {
        id: this.editingTaskId,
        ...this.formModel
      };
      this.taskService.update(request).subscribe({
        next: () => this.afterSaveSuccess(),
        error: (err) => this.afterSaveError(this.buildApiErrorMessage(err, 'Erreur lors de la mise à jour de la tâche'))
      });
      return;
    }

    this.taskService.create(this.formModel).subscribe({
      next: () => {this.afterSaveSuccess(),
         this.cdr.detectChanges();
         this.loadTasks();
      },
      
      
      
      error: (err) => this.afterSaveError(this.buildApiErrorMessage(err, 'Erreur lors de la création de la tâche'))
    });
  }

  openTask(task: TaskDto): void {
    this.router.navigate(['/task/view', task.id]);
  }

  onKanbanCardClick(args: any): void {
    const task = args?.data as TaskDto | undefined;
    if (!task?.id) {
      return;
    }
    this.openTask(task);
  }

  onKanbanActionComplete(args: any): void {
    if (args?.requestType !== 'cardChanged' || !Array.isArray(args?.changedRecords)) {
      return;
    }

    for (const changed of args.changedRecords) {
      const changedId = Number(changed?.id);
      const task = this.tasks.find((current) => current.id === changedId);
      if (!task) {
        continue;
      }

      const updatedStatus = this.normalizeStatus(changed.status as TaskState);
      if (this.normalizeStatus(task.status) === updatedStatus) {
        continue;
      }

      task.status = updatedStatus;

      const request: UpdateTaskRequest = {
        id: task.id,
        title: task.title,
        description: task.description,
        estimatedHours: task.estimatedHours,
        status: updatedStatus,
        complexity: task.complexity ?? 1,
        startDate: this.toDateInput(task.startDate),
        endDate: this.toDateInput(task.endDate),
        userStoryId: task.userStoryId,
        assignedToId: task.assignedToId ?? null,
        sprintId: task.sprintId ?? null
      };

      this.taskService.update(request).subscribe({
        error: () => {
          this.error = 'Erreur lors du changement de statut';
          this.loadTasks();
        }
      });
    }
  }

  getTasksForStatus(status: TaskState): TaskDto[] {
    const normalized = this.normalizeStatus(status);
    return this.tasks.filter(task => this.normalizeStatus(task.status) === normalized);
  }

  getTasksForColumn(statuses: TaskState[]): TaskDto[] {
    const normalizedStatuses = statuses.map((status) => this.normalizeStatus(status));
    return this.tasks.filter((task) => normalizedStatuses.includes(this.normalizeStatus(task.status)));
  }

  openCreateForStatus(status: TaskState, event?: Event): void {
    event?.stopPropagation();
    this.startCreate();
    this.formModel.status = this.normalizeStatus(status);
  }

  moveTaskToStatus(task: TaskDto, targetStatus: TaskState, event: Event): void {
    event.stopPropagation();
    const currentStatus = this.normalizeStatus(task.status);
    const newStatus = this.normalizeStatus(targetStatus);

    if (currentStatus === newStatus) {
      return;
    }

    const request: UpdateTaskRequest = {
      id: task.id,
      title: task.title,
      description: task.description,
      estimatedHours: task.estimatedHours,
      status: newStatus,
      complexity: task.complexity ?? 1,
      startDate: this.toDateInput(task.startDate),
      endDate: this.toDateInput(task.endDate),
      userStoryId: task.userStoryId,
      assignedToId: task.assignedToId ?? null,
      sprintId: task.sprintId ?? null
    };

    this.taskService.update(request).subscribe({
      next: () => {
        task.status = newStatus;
      },
      error: () => {
        this.error = 'Erreur lors du changement de statut';
      }
    });
  }

  moveTaskLeft(task: TaskDto, event: Event): void {
    const index = this.kanbanOrder.indexOf(this.normalizeStatus(task.status));
    if (index > 0) {
      this.moveTaskToStatus(task, this.kanbanOrder[index - 1], event);
    }
  }

  moveTaskRight(task: TaskDto, event: Event): void {
    const index = this.kanbanOrder.indexOf(this.normalizeStatus(task.status));
    if (index >= 0 && index < this.kanbanOrder.length - 1) {
      this.moveTaskToStatus(task, this.kanbanOrder[index + 1], event);
    }
  }

  canMoveLeft(task: TaskDto): boolean {
    return this.kanbanOrder.indexOf(this.normalizeStatus(task.status)) > 0;
  }

  canMoveRight(task: TaskDto): boolean {
    const index = this.kanbanOrder.indexOf(this.normalizeStatus(task.status));
    return index >= 0 && index < this.kanbanOrder.length - 1;
  }

  deleteTask(task: TaskDto, event: Event): void {
    event.stopPropagation();
    const confirmed = window.confirm(`Supprimer la tâche "${task.title}" ?`);
    if (!confirmed) {
      return;
    }

    this.taskService.delete(task.id).subscribe({
      next: () => {
        this.tasks = this.tasks.filter(current => current.id !== task.id);
      },
      error: () => {
        this.error = 'Erreur lors de la suppression de la tâche';
      }
    });
  }

  getStatusLabel(status: TaskState): string {
    const normalized = this.normalizeStatus(status);
    const found = this.statusOptions.find(option => option.value === normalized);
    return found ? found.label : String(status);
  }

  getPriorityLabel(task: TaskDto): string {
    const complexity = task.complexity ?? 1;
    if (complexity >= 4) {
      return 'Haute';
    }
    if (complexity >= 2) {
      return 'Moyenne';
    }
    return 'Basse';
  }

  getPriorityClass(task: TaskDto): string {
    const complexity = task.complexity ?? 1;
    if (complexity >= 4) {
      return 'priority-high';
    }
    if (complexity >= 2) {
      return 'priority-medium';
    }
    return 'priority-low';
  }

  formatDate(value?: string): string {
    if (!value) {
      return '--/--/----';
    }

    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
      return '--/--/----';
    }

    return new Intl.DateTimeFormat('fr-FR').format(date);
  }

  private loadTaskForEdit(taskId: number): void {
    this.taskService.getById(taskId).subscribe({
      next: (task) => {
        this.editMode = true;
        this.editingTaskId = task.id;
        this.formModel = {
          title: task.title,
          description: task.description,
          estimatedHours: task.estimatedHours,
          status: this.normalizeStatus(task.status),
          complexity: task.complexity ?? 1,
          startDate: this.toDateInput(task.startDate),
          endDate: this.toDateInput(task.endDate),
          userStoryId: task.userStoryId,
          assignedToId: task.assignedToId ?? null,
          sprintId: task.sprintId ?? null
        };
      },
      error: () => {
        this.error = 'Impossible de charger la tâche à modifier';
      }
    });
  }

  private afterSaveSuccess(): void {
    this.saving = false;
    this.showForm = false;
    this.editMode = false;
    this.editingTaskId = null;
    this.formModel = this.getEmptyForm();
    this.loadTasks();
  }

  private afterSaveError(message: string): void {
    this.saving = false;
    this.error = message;
  }

  private buildApiErrorMessage(err: any, fallback: string): string {
    const errorMessage = err?.error?.message || err?.error?.title || err?.message;
    return errorMessage ? `${fallback}: ${errorMessage}` : fallback;
  }

  private normalizeStatus(status: TaskState): TaskState {
    const map: Record<number, TaskState> = {
      0: 'pending',
      1: 'todo',
      2: 'inProgress',
      3: 'done',
      4: 'validated'
    };
    return typeof status === 'number' ? map[status] ?? 'pending' : status;
  }

  private toDateInput(value?: string): string {
    if (!value) {
      return new Date().toISOString().slice(0, 10);
    }
    return value.slice(0, 10);
  }

  private getEmptyForm(): CreateTaskRequest {
    const today = new Date().toISOString().slice(0, 10);
    return {
      title: '',
      description: '',
      estimatedHours: 1,
      status: 'pending',
      complexity: 1,
      startDate: today,
      endDate: today,
      userStoryId: this.selectedUserStoryId ?? 0,
      assignedToId: null,
      sprintId: null
    };
  }

  cancelForm(): void {
    this.showForm = false;
    this.editMode = false;
    this.editingTaskId = null;
    this.error = '';
    this.formModel = this.getEmptyForm();
  }

}